// 全局变量
var data = {
  config: null,
  currentPosition: {}, // 用户当前位置信息
  mapAddress: '', // 地图页面选择地址
  addressType: '', // 标记添加地址时的类型 sendStart sendEnd buyStart buyEnd
  addressCityId: '', // 所选地址的cityId，用来在常用地址页面区分列表地址是否在配送范围
  addressInput: { // 快速添加地址页面数据，缓存防止跳转选择地图或者刷新时数据丢失
    detail: '',
    name: '',
    phone: '',
    sex: 1
  },
  sendStart: '', // 帮我送开始地址
  sendEnd: '', // 帮我送结束地址
  sendGoods: '', // 帮我送商品信息
  confirmType: 'send', // 确认订单页的类型 send buy
  confirmBack: false, // 标记是否从确认订单页回到首页
  buyGoodsDesc: '', // 帮我买商品描述
  buyGoodsWeight: {
    weight: 0
  }, // 帮我买商品重量信息
  addressAddType: 1, // 添加地址类型 1是直接添加 2是从地址列表添加
  selectBuyAddress: true, // 帮我买指定地址购买
  estimatedCost: '', // 帮我买 预估商品费用
  imgFiles: [],
  imgList: [],
}

var res = JSON.parse(window.sessionStorage.getItem('paotui_globalData'))
if (data.config == null && res) {
  data = res
  console.log('从缓存中取出globalData', data)
}

var handler = {
  get: function (target, key) {
    if (target[key]) {
      return target[key]
    } else {
      return ''
    }
  },
  set: function (target, key, value) {
    target[key] = value
    console.log('proxy set', target)
    window.sessionStorage.setItem('paotui_globalData', JSON.stringify(target))
    return true
  }
}

var globalData = new Proxy(data, handler)

export default globalData
