<template>
  <div class="home">
    <div class="head" id="head">
      <span class="myself" @click="goMy"><i class="icon iconfont">&#xe63b;</i></span>
      <span>小猪O2O跑腿</span>
    </div>
    <div class="content" id="content">
      <div class="map-box">
        <baidu-map :style="mapH" class="bm-view" ak="4c1bb2055e24296bbaef36574877b4e2" :center="nowMap.center" :zoom="nowMap.zoom" @ready="mapHandler" @dragstart="mapDragstart" @dragend="mapDragend">
          <!-- sendStart点 -->
          <bm-marker :top="true" :position="sendStart.point" :icon="{url: require('../../static/img/send.png'), size: {width:30, height: 30}, opts:{imageSize: {width:30, height: 30}}}" v-if="sendStart != ''"></bm-marker>
          <!-- sendEnd点 -->
          <bm-marker :top="true" :position="sendEnd.point" :icon="{url: require('../../static/img/end.png'), size: {width:30, height: 30}, opts:{imageSize: {width:30, height: 30}}}" v-if="sendEnd != ''"></bm-marker>
          <!-- 骑手点 -->
          <bm-marker :position="item" :icon="{url: require('./imgs/scooter.png'), size: {width:30, height: 30}, opts:{imageSize: {width:30, height: 30}}}" v-for="(item, index) in deliverList" :key="index"></bm-marker>
        </baidu-map>
        <div class="center-icon" v-show="sendStart == ''">
          <div class="desc" v-show="!isdraging">附近有{{ deliverList.length }}位骑手等待为您服务<i class="icon iconfont">&#xe791;</i></div>
        </div>
      </div>
      <div class="input-wrapper" id="inputWrapper">
        <div class="re-location" @click="relocation" v-show="sendStart == ''"><img src="./imgs/location_set.png"></div>
        <div class="clear-address" v-show=" sendStart != '' " @click="clearAddress"><i class="icon iconfont">&#xe64b;</i>清除地址</div>
        <div class="input-box">
          <div class="title">
            <span class="item" :class="{ 'active':isSend }" @click="selectType(true)">帮我送</span>
            <span class="item" :class="{ 'active':!isSend }" @click="selectType(false)">帮我买</span>
          </div>
          <div class="tab-content">
            <div class="send-box" id="sendBox" v-show="isSend">
              <AddressInput addressDesc="从哪里发出" type="sendStart" :addressInfo="sendStart">
                <div class="address-from send" slot="address-from">发</div>
                <div slot="address-tag" class="address-tag" v-show=" addressTag != '' && sendStart == '' && showAddressTag" @click="selectAddressTag">
                  <div class="triangle"><i class="icon iconfont">&#xe792;</i></div>
                  <div class="address">
                    <div class="desc">{{addressTag.adress + addressTag.detail}}</div>
                    <div class="desc">{{addressTag.name + ' ' + addressTag.phone}}</div>
                  </div>
                  <div class="cancel-btn" @click.stop="closeAddressTag"><i class="icon iconfont">&#xe617;</i></div>
                </div>
              </AddressInput>
              <AddressInput addressDesc="送到哪里去" type="sendEnd" :addressInfo="sendEnd">
                <div class="address-from receive" slot="address-from">送</div>
              </AddressInput>
              <SelectGoods :showTxt="sendGoods.showTxt" />
            </div>
            <div class="buy-box" :style="'height:' + sendBoxH + 'px'" v-show="!isSend" @click="clickShowBuyMask">
              <div class="text-box" :style="buyTextBoxH">
                <div class="text">
                  <span v-if=" goodsDesc != '' ">{{goodsDesc}}</span>
                  <span v-else class="placeholder">输入想买的商品，如：1杯星巴克拿铁</span>
                </div>
                <div class="btn" @click="buyGoConfirm('judge')">下单</div>
              </div>
              <div class="icon-box" id="iconBox" >
                <div class="item">
                  <div><i class="icon iconfont">&#xe657;</i></div>
                  <div>小吃</div>
                </div>
                <div class="item">
                  <div><i class="icon iconfont">&#xe803;</i></div>
                  <div>咖啡</div>
                </div>
                <div class="item">
                  <div><i class="icon iconfont">&#xe6b3;</i></div>
                  <div>酒水</div>
                </div>
                <div class="item">
                  <div><i class="icon iconfont">&#xe62d;</i></div>
                  <div>药品</div>
                </div>
                <div class="item">
                  <div><i class="icon iconfont">&#xe61a;</i></div>
                  <div>日用</div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="buy-mask" :class="{'active': showBuyMask}">
        <div class="cancel" @click="clickShowBuyMask(false)"><i class="icon iconfont">&#xe617;</i></div>
        <div class="buy-box">
          <div class="text-box">
            <div class="text">
              <textarea class="input-goods" maxlength="100" placeholder="点击输入你的商品要求，例如糖炒栗子1斤" @input="inputGoodsDesc" v-model="goodsDesc" ></textarea>
            </div>
            <div class="btn" @click="buyGoConfirm">下单</div>
          </div>
          <div class="type-box">
            <div class="title">
              <span class="item" :class="{'active': index === typeNameActive}" v-for="(item, index) in goodsTypeList" :key="index" @click="selectGoodsType(index)">{{item.title}}</span>
            </div>
            <div class="list">
              <span class="item" @click="selectGoods(item)" v-for="(item, index) in goodsTypeList[typeNameActive].goods" :key="index">{{item}}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import AddressInput from '../../components/AddressInput/AddressInput'
import SelectGoods from '../../components/SelectGoods/SelectGoods'
import BaiduMap from 'vue-baidu-map/components/map/Map.vue'
import BmMarker from 'vue-baidu-map/components/overlays/Marker'

export default {
  name: 'home',
  data () {
    return {
      isSend: true, // true表示"帮我送"，false表示"帮我买"
      mapH: 0, // 地图组件高度
      sendBoxH: '', // 帮我买区域高度
      buyBoxStyle: '',
      isFirst: true, // 是否第一次打开页面
      buyTextBoxH: 122, // 帮我送文本区域高度
      goodsTypeList: [
        { title: '小吃', goods: ['冰糖葫芦', '糖炒栗子', '酸奶', '煎饼', '奶茶', '鸭脖', '馄饨', '烤肉饭', '水饺', '生煎', '1份', '与我联系'] },
        { title: '咖啡', goods: ['星巴克', 'costa咖世家', '黑森林拿铁', '卡布奇诺', '拿铁', '美式', '摩卡', '馥芮白', '焦糖玛奇朵', '抹茶星冰乐', '超大杯', '大杯'] },
        { title: '酒水', goods: ['啤酒', '白酒', '红酒', '威士忌', '青岛', '百威', '雪花', '五粮液', '剑南春', '二锅头', '开瓶器', '1瓶', '1罐', '与我联系'] },
        { title: '药品', goods: ['999感冒灵', '体温计', '滴眼液', '隐形眼镜护理液', '隐形眼镜', '避孕药', '验孕棒', '避孕套', '芬必得', '1盒'] },
        { title: '日用', goods: ['苹果数据线', '安卓数据线', '暖宝宝', '雨伞', '卫生巾', '纸巾', '胶带', '洗发水', '电池', '插座', '扑克牌', '1个', '与我联系'] }
      ],
      typeNameActive: 0, // "帮我买"选择物品分类
      showBuyMask: false, // 显示"帮我买"弹窗
      goodsDesc: '', // "帮我买"填写的商品描述
      showAddressTag: true, // 是否显示提示地址
      showAddressClear: false, // 是否显示地址清除按钮
      nowMap: { // 地图配置
        center: { lng: 0, lat: 0 }, // 地图中心点位置
        zoom: 15 // 地图缩放级别
      },
      current: { lng: 0, lat: 0 }, // 用户当前定位坐标
      deliverList: [], // 附近配送员列表
      isdraging: false, // 是否拖拽地图当前位置标记
      sendStart: '', // 帮我送初始地址
      sendEnd: '', // 帮我送结束地址
      addressTag: '', // 帮我送地址提示
      sendGoods: '', // 帮我送商品信息
    }
  },
  created () {
    this.isSend = this.$globalData.confirmType == 'send'
    this.sendGoods = this.$globalData.sendGoods
    this.$globalData.time = ''
    this.$globalData.tip = ''
    this.$globalData.imgFiles = []
    this.$globalData.imgList = []
    if (this.$globalData.confirmBack) {
      this.$globalData.confirmBack = false
      this.$globalData.sendStart = this.sendStart = ''
      this.$globalData.sendEnd = this.sendEnd = ''
    } else if (this.isSend) {
      this.sendStart = this.$globalData.sendStart
      this.sendEnd = this.$globalData.sendEnd
      if (this.sendStart != '' && this.sendEnd != '' && this.sendGoods != '') {
        this.$router.push('/confirm')
      }
    } else {
      this.$globalData.buyGoodsWeight = { weight: 0 }
      this.$globalData.buyStart = ''
      this.$globalData.buyEnd = ''
      this.$globalData.estimatedCost = ''
      this.goodsDesc = this.$globalData.buyGoodsDesc
    }

    this.getConfig()
  },
  mounted () {
    if (this.isSend) {
      this.sendBoxH = document.getElementById('sendBox').getBoundingClientRect().height
    }
    this.mapH = `height:${document.getElementById('content').getBoundingClientRect().height - document.getElementById('inputWrapper').getBoundingClientRect().height - document.getElementById('head').getBoundingClientRect().height}px`

  },
  methods: {
    // 选择跑腿方式
    selectType (isSend) {
      if (this.isSend == isSend && !this.isFirst) {
        return
      }
      this.isSend = isSend
      this.$globalData.confirmType = isSend ? 'send' : 'buy'
      if (this.isFirst) {
        if (this.isSend) {
          this.$nextTick(function () {
            this.sendBoxH = document.getElementById('sendBox').getBoundingClientRect().height
          })
        } else {
          this.$nextTick(function () {
            this.isFirst = false
            this.buyTextBoxH = `height:${this.sendBoxH - document.getElementById('iconBox').getBoundingClientRect().height}px`
          })
        }
      }
    },
    // 选择商品类别
    selectGoodsType (index) {
      this.typeNameActive = index
    },
    // 是否显示“帮我买”弹窗
    clickShowBuyMask (isShow) {
      if (isShow) {
        this.showBuyMask = isShow
        return
      }
      this.showBuyMask = !this.showBuyMask
    },
    // 选择商品标签
    selectGoods (value) {
      if (this.goodsDesc.length > 100) {
        this.$toast('最多只能输入100个字')
        return
      }
      if (this.goodsDesc === '') {
        this.goodsDesc = value
        this.$globalData.buyGoodsDesc = this.goodsDesc
        return
      }
      this.goodsDesc += ' ' + value
      this.$globalData.buyGoodsDesc = this.goodsDesc
    },
    // 输入商品信息
    inputGoodsDesc (e) {
      if (this.goodsDesc.length >= 100) {
        this.$toast('最多只能输入100个字')
      }
      this.$globalData.buyGoodsDesc = this.goodsDesc
    },
    // 关闭地址小蒙层
    closeAddressTag () {
      this.showAddressTag = false
    },
    // 打开个人中心
    goMy () {
      if (this.$util.checkLogin()) {
        this.$router.push('myself')
      }
    },
    // 地图初始化
    mapHandler ({ BMap, map }) {
      console.log(BMap, map)
      if (this.sendEnd != '') {
        var viewportOptions = {
          zoomFactor: -1
        }
        this.nowMap = map.getViewport([this.sendStart.point, this.sendEnd.point], viewportOptions)
        this.getDeliverList()
        return
      }
      if (this.sendStart != '') {
        this.nowMap.center = this.sendStart.point
        this.current = this.$globalData.currentPosition
        this.getDeliverList()
        return
      }
      this.nowMap.center = { lng: 116.331398, lat: 39.897445 }
      this.locationEvent()
    },
    // 获取定位
    locationEvent () {
      var _this = this
      if (this.$util.checkLifeApp()) {
        this.$util.appFunction({ name: 'getlocation', callback: 'locationOk' })
      } else {
        // eslint-disable-next-line
        var geolocation = new BMap.Geolocation()
        geolocation.getCurrentPosition(function (r) {
          // eslint-disable-next-line
          let successStr = BMAP_STATUS_SUCCESS
          if (this.getStatus() == successStr) {
            _this.nowMap.center = { lng: r.longitude, lat: r.latitude }
            _this.getDeliverList()
            if (_this.current.lng == 0 && _this.current.lat == 0) {
              var myGeo = new BMap.Geocoder()
              myGeo.getLocation(new BMap.Point(r.longitude, r.latitude), function (result) {
                console.log('33333355555555', result)
                r.address = result.addressComponents
                r.address.business = result.business
                r.address.total = result.address
                _this.$globalData.currentPosition = r
              })
              _this.current = _this.nowMap.center
            }
          } else {
            console.log('h5页面获取定位失败', this.getStatus())
          }
        })
      }
    },
    // 获取定位成功
    locationOk (name, lng, lat) {
      console.log(name, lng, lat)
    },
    // 获取config
    async getConfig () {
      try {
        let res = await this.$api.getConfig()
        if (!res.errorMsg) {
          this.config = this.$globalData.config = res
        }
      } catch (e) {
        console.log('跑腿首页获取config发生错误 getConfig', e)
      }
    },
    // 获取附近配送员
    async getDeliverList () {
      try {
        var param = this.nowMap.center
        param.type = 'baidu'
        let res = await this.$api.getDeliverList(param)
        if (!res.errorMsg) {
          this.deliverList = res.returnDeliver
          res.userAdress.point = { lng: res.userAdress.longitude, lat: res.userAdress.latitude }
          this.addressTag = res.userAdress
        }
      } catch (e) {
        console.log('跑腿首页获取附近配送员列表发生错误 getDeliverList')
      }
    },
    // 地图拖拽开始
    mapDragstart () {
      this.isdraging = true
    },
    // 地图拖拽结束
    mapDragend ({ type, target, pixel, point }) {
      this.isdraging = false
      this.nowMap.center = target.getCenter()
      this.getDeliverList()
    },
    // 点击地图右下角定位按钮
    relocation () {
      if (this.current.lng != this.nowMap.center.lng || this.current.lat != this.nowMap.center.lat) {
        this.locationEvent()
      }
    },
    // 清除地址
    clearAddress () {
      this.$globalData.sendStart = this.sendStart = ''
      if (this.sendEnd != '') {
        this.$globalData.sendEnd = this.sendEnd = ''
      }
      this.nowMap.zoom = 15
    },
    // 点击地址弹层
    selectAddressTag () {
      this.$globalData.sendStart = this.sendStart = this.addressTag
      this.nowMap.center = { lng: this.sendStart.longitude, lat: this.sendStart.latitude }
    },
    buyGoConfirm (type) {
      if (type === 'judge' && !this.goodsDesc) {
        this.showBuyMask = true
        return
      }
      if (this.$util.checkLogin()) {
        this.$globalData.confirmType = 'buy'
        this.$router.push('/confirm')
      }
    }
  },
  components: {
    AddressInput,
    SelectGoods,
    BaiduMap,
    BmMarker
  }
}
</script>

