<template>
  <div class="address-input">
    <slot name="address-from" ></slot>
    <div class="detail-box">
      <div class="info-box" @click="goAdd">
        <div class="address-desc" v-if="addressInfo == ''">{{addressDesc}}</div>
        <div class="address-box " v-else>
          <div class="address">{{addressInfo.adress + ' ' + addressInfo.detail}}</div>
          <div class="user">{{addressInfo.name + ' ' + addressInfo.phone}}</div>
        </div>
      </div>
      <div class="right-btn" @click="goSelect">常用</div>
      <slot name="address-tag"></slot>
    </div>
  </div>
</template>

<script>
export default {
  name: 'AddressInput',
  data () {
    return {}
  },
  props: ['addressDesc', 'type', 'addressInfo'],
  methods: {
    goSelect () {
      if (this.isSend()) {
        this.$router.push('/selectaddress')
      }
    },
    goAdd () {
      if (this.isSend()) {
        this.$globalData.addressAddType = 1
        this.$globalData.addressInput = this.addressInfo
        this.$router.push('/addaddress')
      }
    },
    isSend () {
      if (this.$util.checkLogin()) {
        if (this.type == 'sendEnd' && this.$globalData.sendStart == '') {
          this.$toast('请先填写发件地址')
          return false
        } else {
          this.$globalData.addressType = this.type
          this.isHaveCityId()
          return true
        }
      }
    },
    isHaveCityId () {
      if (this.type == 'sendStart') {
        this.$globalData.addressCityId = this.$globalData.sendEnd != '' ? this.$globalData.sendEnd.city : ''
      }

      if (this.type == 'sendEnd') {
        this.$globalData.addressCityId = this.$globalData.sendStart.city
      }

      if (this.type == 'buyStart') {
        this.$globalData.addressCityId = this.$globalData.buyEnd != '' ? this.$globalData.buyEnd.city : ''
      }

      if (this.type == 'buyEnd') {
        this.$globalData.addressCityId = this.$globalData.buyStart != '' ? this.$globalData.buyStart.city : ''
      }
    }
  }
}
</script>

<style lang="stylus" scoped>
.address-input
  background #fff
  font-size 14px
  color #999
  flexbox()
  align-items center
  .detail-box
    margin-left 10px
    width -webkit-calc(100% - 30px)
    width calc(100% - 30px)
    flexbox()
    flex-grow 1
    align-items center
    border-bottom 1PX solid #eee
    position relative
    .info-box
      width -webkit-calc(100% - 70px)
      width calc(100% - 80px)
      flex-grow 1
      margin-right 15px
      line-height 1.8
      .address-box
        .address
          color #333
          ellipsis(1)
        .user
          ellipsis(1)
    .right-btn
      background $color-main
      color #fff
      padding 8px 10px
      border-radius 5px
      margin 15px 0 15px 15px
      position relative
      flex-shrink 0
      &::after
        content ''
        width 1PX
        height 40px
        background #eee
        position absolute
        top -5px
        left -15px
</style>
