<template>
  <div id="app">
    <router-view/>
  </div>
</template>
<script>
export default {
  created () {
    if (this.$util.checkLifeApp()) {
      if (!this.$util.getTicket() && this.$util.storage.get('ticket')) {
        this.$util.storage.remove('ticket')
        this.$util.storage.remove('device')
      } else if (this.$util.getTicket()) {
        this.$util.storage.set('ticket', this.$util.getTicket())
        this.$util.storage.set('device', this.$util.getDeviceid())
      }
    } else {
      if (this.$util.cookie.get('login_status') && this.$util.cookie.get('login_status') == 'login') {
        this.$util.storage.set('ticket', this.$util.cookie.get('user_ticket'))
        this.$util.cookie.get('user_device_id') && this.$util.storage.set('device', this.$util.cookie.get('user_device_id'))
      } else if (this.$util.cookie.get('login_status') == 'logout') {
        console.log('清除ticket', this.$util.cookie.get('login_status'))
        this.$util.storage.remove('ticket')
        this.$util.storage.remove('device')
      }
    }
  }
}
</script>
<style lang="stylus" scoped>
#app
  -webkit-font-smoothing antialiased
  -moz-osx-font-smoothing grayscale
  height 100%
  color #333
  background #f2f2f2
  overflow hidden
  position absolute
  left 0
  top 0
  bottom 0
  right 0
</style>
