import Vue from 'vue'
import Router from 'vue-router'
import Home from './pages/Home/Home.vue'

Vue.use(Router)

const router = new Router({
  // mode: 'history',
  base: process.env.BASE_URL,
  routes: [
    {
      path: '/',
      redirect: '/home'
    },
    {
      path: '/home',
      name: 'home',
      component: Home
    },
    {
      path: '/selectaddress',
      name: 'selectAddress',
      component: () => import('./pages/SelectAddress/SelectAddress.vue')
    },
    {
      path: '/addaddress',
      name: 'addAddress',
      component: () => import('./pages/AddAddress/AddAddress.vue')
    },
    {
      path: '/goodstype',
      name: 'goodsType',
      component: () => import('./pages/GoodsType/GoodsType.vue')
    },
    {
      path: '/myself',
      name: 'myself',
      component: () => import('./pages/Myself/Myself.vue')
    },
    {
      path: '/confirm',
      name: 'confirm',
      component: () => import('./pages/Confirm/Confirm.vue')
    },
    {
      path: '/openmap',
      name: 'openMap',
      component: () => import('./pages/openMap/openMap.vue')
    }
  ]
})

export default router
